    if not val.endswith(']'):
        val = val + ']'
    try:
        return json.loads(val)
    except Exception as e:
        return []

match = 0
mismatch = 0
for idx, row in df_time.iterrows():
    tasks = parse_tasks(row['performed_tasks'])
    inv = [t for t in tasks if t not in task_map]
    if not inv:
        s = sum(task_map[t] for t in tasks)
